-- ============================================================
--  Du Golf & des Amis — PARCOURS (données RÉELLES complètes)
--  Départ jaune. Pour chaque trou : Par + HCP + Longueur (m).
--  Longueur totale = cumul des trous (champ length + tee Jaune).
--  Relevé sur les cartes de score officielles.
--  À coller dans Supabase → SQL Editor → Run (après schema.sql + open_access.sql).
--  Idempotent : on efface les parcours seed puis on réinsère.
-- ============================================================

delete from public.courses where (data->>'source') is null;


-- Vérif : nom, par total, longueur cumulée, slope jaune
select data->>'name' as parcours, data->>'par' as par,
       data->>'length' as long_m, (data->'tees'->0->>'slope') as slope_jaune
from public.courses order by parcours;
